INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlindJump', 'Blind Jump is a simple action/adventure game, featuring procedurally generated level maps, collectible items, fluid animation, and meticulously designed color palettes. Evan Bowman started the project in late 2015 while in college, and resumed work on the code after a several year long hiatus, during which he was teaching himself oil painting. Originally developed for macOS, the game was rebuilt from scratch during the 2020 pandemic, with a new custom engine. Blind Jump now compiles for various other platforms, including Linux, Windows, Nintendo Gameboy Advance, and Sony PlayStation Portable.' FROM games WHERE igdb_id = 249526 ON CONFLICT (game_id, language_code) DO NOTHING;
