INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Switchy Road DeluX', 'The widely popular Switchy Road endless roller now comes in a new enhanced deluxe version. The challenging road crossing game now has amazing new levels each with different themes, backgrounds, designs and music! Play starts with the original Switchy Road theme but with skill you will quickly progress through each level to unlock the next unique theme. Once you unlock them all you can go back and select whichever level you want to play again. Play all the levels or stick with your favorite ones. Random generated crossing roads make the challenge different every time you play.' FROM games WHERE igdb_id = 147608 ON CONFLICT (game_id, language_code) DO NOTHING;
