INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winging It', 'Experience the spring as a bluebird. Choose the material for your nest, feast on nature’s bounty in the form of seeds, berries, and worms, and participate in quintessential bird activities. Most of all, take care of your eggs to make sure they hatch safe and sound. And, remember: don’t give up!' FROM games WHERE igdb_id = 180351 ON CONFLICT (game_id, language_code) DO NOTHING;
