INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fraulein Lolita First Date With You', '这是一款美少女+卡牌相结合的同人游戏。游戏将用卡牌呈现你与洛璃在圣诞夜的浪漫约会，约会就像是一场战斗，巧妙地化解约会中的各种尴尬，寻找突破口，与洛璃一同度过甜蜜一夜吧！使用卡牌解决发生的事件，你要如何应对女友偶然的小脾气呢？赌上尊严和器量，洛璃的征服战——开幕！' FROM games WHERE igdb_id = 157955 ON CONFLICT (game_id, language_code) DO NOTHING;
