INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ao-jian-qing-yuan', 148618, '2020-11-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57z1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arn7p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '傲剑情缘', '纷纷江湖路，萧萧武侠情。有人的地方就有江湖。我辈人才倍出，在江湖上呈现出了新的一场百家争鸣、八仙过海各显神通的精彩竞争。《傲剑情缘》是一款全新的以武侠江湖题材背景的RPG游戏。 精美的人物刻画、丰富真实的江湖场景、热血刺激的打斗渲染，给你身临其境的直观游戏感受。天纵英才群侠出，铁血豪情论英雄。这里有上百个极具特色、风格迥异的武侠等待你的召唤，与你一起结伴而行，共闯天涯路。' FROM games WHERE igdb_id = 148618 ON CONFLICT (game_id, language_code) DO NOTHING;
