INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzles for Toddlers & Kids: Animals, Cars and more', 'This puzzle game is extremely easy to use and was tailored with great care to be played by children of all ages. It is battle-tested and 100% frustration free. It contains different difficulty-levels for entertaining a wide range of age-groups. Balloons and Bubbles can be popped at the end of each puzzle, adding extra fun to the game. The game can be configured to make it even more easy to use, so children of all ages can enjoy the gaming experience with no frustration while still being challenged as appropriate for their age. The puzzles come in themed packages with 30 puzzles each, so there are puzzles for every liking.' FROM games WHERE igdb_id = 147707 ON CONFLICT (game_id, language_code) DO NOTHING;
