INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vikings of Midgard', 'Vikings of Midgard is a retro-style turn-based RPG about a group of heroes (10 in total with their strengths) travelling across an expansive world that changes with the players actions. The setting is inspired by Norse Mythology but contains other eclectic and eccentric influences. The game also has helpful features like being able to turn off random encounters and an in-game library bereft with information.' FROM games WHERE igdb_id = 182031 ON CONFLICT (game_id, language_code) DO NOTHING;
