INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taxi Sim 2020', 'Experience the life of a taxi driver in our latest taxi simulator game. Complete different types of driving missions as a taxi or private taxi driver and pick your favorite car from a selection of over 30 amazing vehicles, with more new cars being added weekly. Navigate around huge cities like New York, Miami, Rome or Los Angeles and adjust your driving style to different types of clients - some are in a hurry and don''t care if you run a red light, while others are terrified of dangerous driving.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 147629 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
