INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Make a Good Mega Man Level: Episode Zero', 'MaGMML: Episode Zero, an interquel set between the events of MaGMML1 and MaGMML2, is a massive collaboration fangame brought to you by the team behind the MaGMML series! Play as the legendary (?) Reploid (?) Zero as he journeys through over 60 different levels from 40 different creators in a unique blend of Mega Man Classic, X, Zero, and ZX! Blast through levels with the aimable Z-Buster, the trusty Z-Saber, the long-range Z-Burst, and the wildcard Blank Drive, all backed by an expanded version of the elemental chip system from the Zero series.' FROM games WHERE igdb_id = 197785 ON CONFLICT (game_id, language_code) DO NOTHING;
