INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic 3D in 2D', 'Sonic 3D in 2D is a fangame that reimagines Sonic3D Blast plot and levels with style and structure closer to the games that preceeded it. Explore Flicky Island in a 2D side scrolling platformer that takes elements from the other Mega Drive/Genesis games to re-forge an adventure anew. Fight new and challenging bosses, save Flicky Island and stop Robotnik''s final plan to harness the Flicky''s power for himself.' FROM games WHERE igdb_id = 177697 ON CONFLICT (game_id, language_code) DO NOTHING;
