INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trollface-quest-horror-3', 101907, '2020-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6e9e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm644.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TrollFace Quest: Horror 3', 'TrollFace is always delighting us with new parodies of famous movies, games or TV series. Unusual heroes like to joke on everyone, and everyone can be a victim of another prank. In the game "TrollFace Quest: Horror 3", you will plunge into an atmosphere of fear, which will become a hilarious farce with the help of trolls. In this game, new horror movies, as well as classic retro horror movies, come under the banter of bullies. If you''ve been frightened by such movies before, now they''ll make you laugh. Granny Babka, Dracula, The Mummy, Resident Evil, The Ring and other already classic horror industry movies will be the center of your fun and make you develop your logical abilities. Each level has two options for the development of the plot. Your goal is to find just the right solution to the episode and you can move on to the next fun level.On the first level you will meet Granny''s grandmother. Crazy old woman meets you with a club, and is waiting for your actions. What to do will be up to you to decide whether you can continue your adventures in Trollface Quest. Enjoy the game and good luck!' FROM games WHERE igdb_id = 101907 ON CONFLICT (game_id, language_code) DO NOTHING;
