INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Ball', 'Panzer Ball is about speed and agility. Complete races in this fast-paced 3D platformer that is inspired by the classic surf maps and bunnyhop modes from games of the past. This game includes both a singleplayer and a multiplayer experience. The online multiplayer is fully real-time so you can invite your friends and see who gets the fastest time. Join our community to get involved in experimental modes, early playtests and be part of the development of Panzer Ball.' FROM games WHERE igdb_id = 132338 ON CONFLICT (game_id, language_code) DO NOTHING;
