INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buster''s Quest: Trials of Hamsterdam', 'Buster''s Quest is a classic action-puzzle game focused on solving increasingly complex puzzles. Play as Buster or Busterina as you traverse lands filled with cute cuddly enemies determined to stop you at all costs. Collect hamsterballs, shoot enemies and get the fastest times as you climb the online leaderboards. Learn enemy quirks to quickly vanquish them and progress to the next level. With over 150 levels, the challenge to save your significant other has never been so daunting.' FROM games WHERE igdb_id = 143881 ON CONFLICT (game_id, language_code) DO NOTHING;
