INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kin''iro Loveriche', 'Noble Private Academy: it is where the ladies and gentlemen of the future are raised. At this boarding school, students not only learn basic education but are also taught how to be dignified. This year is especially unique since royalty from the small Scandinavian country of Sortilège was invited to the school. Ouro caught the eye of the princess Sylvia after a certain incident, which led to him being beaten up at the school and ultimately placed into a vacant room in the girls’ dormitory.' FROM games WHERE igdb_id = 136754 ON CONFLICT (game_id, language_code) DO NOTHING;
