INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('piczle-lines-dx-bundle', 147788, '2020-08-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5aoh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbd9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piczle Lines DX Bundle', 'Both Piczle Lines DX and Piczle Lines DX 500 More Puzzles! are stuffed together in this ridiculously puzzle-heavy game bundle! Totalling 1,100 logic-puzzles and an estimated clear time of 150~200 hours this bundle is going to keep you occupied for a looong time. Draw lines to connect pairs of numbers to complete a hidden picture in this feverishly addictive PICture puzZLE game! Connect numbers of the same color, using the same number of blocks as the number. 100 story mode puzzles, plus 500 themed puzzle packs from Piczle Lines DX and 500 more from Piczle Lines DX 500 More Puzzles!, featuring gorgeous Piczle art like the Arc De Triomphe, Mona Lisa, Beethoven, Alice''s Adventures in Wonderland and the confounding one-colour puzzle pack. Plus "The Art of Piczle", a special 36 page behind-the-scenes look at some of the art created by Score Studios.' FROM games WHERE igdb_id = 147788 ON CONFLICT (game_id, language_code) DO NOTHING;
