INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasia Re:Build', 'Fantasia Rebuild is a role-playing mobile game launched by DMM GAMES. It will bring together the characters of the Fantasia Library''s many works, including "Date A Live", "Slayers", "Saekano: How to Raise a Boring Girifriend" and so on. The overall world view of this work is carried out by the Koshi Tachibana, and the original character design is designed by Kurone Mishima and blkawa Kanetake. Although the official game system has not yet been released, from the propaganda words, this will be a "RPG weaved in the lost world."' FROM games WHERE igdb_id = 111282 ON CONFLICT (game_id, language_code) DO NOTHING;
