INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frosty Jump', 'Join Frosty on his quest and meet all his new snow friends! Play as Mrs. Frosty, Space Frosty and Cowboy Frosty! Collect over 50 additional Frosty friends! Avoid enemies and use your power-ups as you jump along this snowy endless jumping adventure! • Help Frosty jump through endless frozen levels! • Over 50 different playable snow friends to collect! • Awesome power-ups to help Frosty escape! • Perfect for endless year-round fun!' FROM games WHERE igdb_id = 147148 ON CONFLICT (game_id, language_code) DO NOTHING;
