INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kumi-Daiko Beatoff 64', 'Kumi-Daiko Beatoff 64 is a Nintendo 64 homebrew game by Team Riistahillo and released on 13 December 2020. This is an arcade-style game where you control a kabuki mask spinning a taiko drum around to fight off floating tengu masks. This game was made for the 64brew game jam 2020, and won 2nd place alongside Sblobber 64.' FROM games WHERE igdb_id = 145458 ON CONFLICT (game_id, language_code) DO NOTHING;
