INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dontdy', 'Dontdy is a Deathrun and troll game where you have to go from point A to point B without dying. In this city or even this castle which seems peaceful at first glance, there are deadly traps. So be careful where you walk. Otherwise you will go mad. And this game is far from being a hiking simulator.' FROM games WHERE igdb_id = 156108 ON CONFLICT (game_id, language_code) DO NOTHING;
