INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('number-nolimitfantasy-super-puzzles-dream', 146680, '2020-08-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ylm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar92d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '#NoLimitFantasy, Super Puzzles Dream', 'Puzzles move onto the next level with ‘Super Puzzle Dream’, a mix between classic jigsaw and a ‘Tetris’-style dynamic mechanic. #NoLimitFantasy! is the hashtag for this section. Devoted to the necessary and forgotten world of fantasy featuring illustrations and motivational messages after each puzzle is completed. Two levels of play, ''senior'' (for adults) and ''junior'' (for children aged 3+), guarantee hours of entertainment for all. Become an expert and finish the puzzles in the shortest possible time and you will find yourself amongst the best in the world on the online leaderboard. You can also play with friends and family in the one-on-one split-screen competition mode. Your rival won''t make it easy for you! Don''t give up - fill an energy bar to perform a counterattack and put them in their place. Get the 3 stars in the 25 jigsaw puzzle with 7 difficulties each. This gives the game great replayability.. Remember, without fun there is no « Super Puzzles Dream »' FROM games WHERE igdb_id = 146680 ON CONFLICT (game_id, language_code) DO NOTHING;
