INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Fury First Contact', 'Those legendary wolves stake their claim on a new stage! Utilize earth-shattering special moves and reach for the top! - FATAL FURY newcomers like Rick Strowd and Li Xiangfei clash fists with nostalgic fan-favorites Terry, Geese, and Mai Shiranui! - Easier for beginners thanks to single-lane fighting! Unleash an ultra-lethal POTENTIAL POWER move at the brink of death to turn the tables on your foes! - Invite a friend over for some 1on1 action in either tabletop or handheld mode! Find out who has what it takes to be hailed as the best in Southtown! *The game manual included is from the NEOGEO POCKET COLOR edition and therefore contains control schemes which may vary from those on the Nintendo Switch.' FROM games WHERE igdb_id = 44004 ON CONFLICT (game_id, language_code) DO NOTHING;
