INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('variations-on-coda-to-yellow-sky-im-slash-perfect-dawn-repeat', 140136, '2020-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2iv5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8o96.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Variations on Coda to Yellow Sky (Im/Perfect Dawn: Repeat)', '“variations…” is a contemplative short role playing game about setting and adjusting personal goals and the various ways humans attempt to reconcile with the approach of death. its recursively looping “active-time preparation” structure reinterprets various visual and mechanical genre tropes in service of a collection of intimate ruminations and a genuine moral and practical dilemma. the player takes on the role of a monk in a medieval monastery in the final hour before the dawn arrival of a brutal invading army. through exploring the building and conversing with their various contrasting peers, the player is given the chance to set and then carry out their own objectives for dealing with the impending collective fate.' FROM games WHERE igdb_id = 140136 ON CONFLICT (game_id, language_code) DO NOTHING;
