INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elite of Mboa', 'The Elite of Mboa is a satirical life sim game from Cameroonian developer Kiro''o Games. Set in the fictional "very very democratic republic of Mboa", this sendup of African politics puts players in the shoes of a very ordinary man stepping into his first week on the job in the General Ministry of His Excellency Mougabiang. Players make countless choices over the course of their careers, from whether to follow a corrupt or honest path in politics to where to spend their time and money at night, with many different branching story paths.' FROM games WHERE igdb_id = 260491 ON CONFLICT (game_id, language_code) DO NOTHING;
