INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wwe-undefeated', 140927, '2020-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kwg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar22sx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE Undefeated', 'Play the newest WWE mobile game featuring real-time head-to-head competition. Designed from the ground up for mobile, this multiplayer action game presents quick-session matches that blend fast arcade-style action with strategic depth of an RPG. Collect and upgrade signature moves to build up your WWE Superstar’s and Legend’s arsenal to dominate and defeat your opponents. Play as your favorite WWE Superstars and Legends, including The Rock, Roman Reigns, The Undertaker, Drew McIntyre, “The Fiend” Bray Wyatt, Seth Rollins, Kofi Kingston, and more. Experience over-the-top action with outrageous attacks, exaggerated poses, and unbelievable moves. Connect with a faction to share moves and strategies. Show the world what you’ve got on your epic quest to become the ultimate WWE Champion.' FROM games WHERE igdb_id = 140927 ON CONFLICT (game_id, language_code) DO NOTHING;
