INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extra Ordinary', 'Short retro-inspired game based on Extra Ordinary (2019) a supernatural horror-comedy film directed by Mike Ahern & Enda Loughman. You play as Rose, a (mostly sweet and mostly lonely) Irish small-town driving instructor, who must use her supernatural talents to save the daughter of Martin (also mostly sweet & lonely) from a washed-up rock star who plans to use her in a Satanic pact to reignite his fame.' FROM games WHERE igdb_id = 305228 ON CONFLICT (game_id, language_code) DO NOTHING;
