INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape From the Hospital', 'Escape from the hospital is a small quest puzzle. You find yourself in an abandoned hospital for unknown reasons and you have no choice but to start looking for a way out. On your way you will meet various monsters and not difficult puzzles. The playing time is about 30-40 minutes.' FROM games WHERE igdb_id = 100742 ON CONFLICT (game_id, language_code) DO NOTHING;
