INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Incursion', 'Sonic Incursion is a fangame utilizing the Sonic GDK extension to the Unreal Development kit. Play as Sonic or Metal Sonic as you take the fight to the vicious Metallix Empire, before they convert all life into twisted mechanical beings! The gameplay is 2.5D for the regular stages, with certain Act 3''s featuring singular gimmicks.' FROM games WHERE igdb_id = 326998 ON CONFLICT (game_id, language_code) DO NOTHING;
