INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('virus-the-outbreak', 147478, '2020-12-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59ff.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9hp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virus: The Outbreak', 'In Virus: The Outbreak we allow the players to face the most current and touching topic of all - a pandemic of a dangerous virus. As the leader of the Global Health Organization (GHO) your task is to contain the spread of a virus and save humanity before it is too late. In addition to crisis management, the game provides the players with information on how to behave in the event of an epidemic, what actions to take, and how to protect themselves and their loved ones in the most effective way. The game is based on the data published by WHO and on the information acquired from experts and consultants. Through your actions, you will be able to see how difficult it is to manage during a crisis, what impact various decisions can have on an effective fight against a global epidemic, which can be caused by listening to charlatans or the lack of appropriate medical equipment.' FROM games WHERE igdb_id = 147478 ON CONFLICT (game_id, language_code) DO NOTHING;
