INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lies Beneath', 'LIES BENEATH is a single-player survival horror game with a heavy dose of action! Something''s gone horribly wrong in the sleepy town of Slumber, Alaska. Now, returning college student Mae must fight to save her father (and her sanity) from the terrifying townsfolk and creepy creatures infecting her hometown. Experience a living comic book full of frightful scenarios as you uncover the secrets of Slumber… and Mae''s past.' FROM games WHERE igdb_id = 133280 ON CONFLICT (game_id, language_code) DO NOTHING;
