INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Long Goodbye', 'A Long Goodbye is a short narrative game centered around two old friends who have to say their final goodbye over a phone conversation. The game focuses on using a realistic conversation structure, with each reply moving the conversation down a new winding path. Play through multiple times to explore new topics and learn more about the characters, their shared history, estrangement, and the things left unsaid.' FROM games WHERE igdb_id = 283528 ON CONFLICT (game_id, language_code) DO NOTHING;
