INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexxagon - Board Game', 'The object of the game is to make your pieces constitute a majority of the pieces on the board at the end of the game, by converting as many of your opponent''s pieces as possible. You can play against a friend or alone in arcade mode with increasing difficulty. The game will test you tactic skills and entertain you and your friends. Dominate the board and climb the leaderboard. Based on an early 90''s arcade game.' FROM games WHERE igdb_id = 147988 ON CONFLICT (game_id, language_code) DO NOTHING;
