INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem: Shadow Dragon and the Blade of Light - 30th Anniversary Edition', 'This collector’s edition of the game will include a nostalgic, stylized physical NES box and a replica NES Game Pak art piece with a protective sleeve that transports owners to the era of the original game’s release. The collector’s edition also includes a colorful, 222-page Legacy of Archanea deluxe hardbound art book and a game download code. It will be accompanied by an NES instruction manual, newly localized from the original Famicom release, along with a fold-out world map and a Mini Nintendo Power retro collectible.' FROM games WHERE igdb_id = 140611 ON CONFLICT (game_id, language_code) DO NOTHING;
