INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Fried Nikki', 'Deep Fried Nikki is an English Yume Nikki fangame. It was made as a late April Fool''s joke, satirizing fangames that are essential re-skins of Yume Nikki. It plays just like Yume Nikki, but with different graphics and music, and with an additional ending located in the White Desert.' FROM games WHERE igdb_id = 229667 ON CONFLICT (game_id, language_code) DO NOTHING;
