INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Telocation: Gemini', 'Telocation: Gemini (sometimes just Telocation) is a Nintendo 64 homebrew game by the Ultra Rare team and released on 13 December 2020. In it, you control a crashlanded space cadet that befriends a robot and who work together to gather gems and escape the planet. This game was made for the 64brew game jam 2020, and won 1st place.' FROM games WHERE igdb_id = 145455 ON CONFLICT (game_id, language_code) DO NOTHING;
