INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Powertris', 'Powertris is a shocking mixture of well-known classics - Tetris and Pipermania. By placing blocks, the player must pay attention to whether both sides of the system are connected with the sockets on the edges of the screen. During the game, the player will have to make quick decisions as well as use special blocks.' FROM games WHERE igdb_id = 147136 ON CONFLICT (game_id, language_code) DO NOTHING;
