INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whisper', 'Whisper is a puzzle game about sound shaping our reality. Human perception is guided by visual input. We know that a tree is a tree because it looks like a tree. What if we took that away? If you hear the sound of a falling tree, but no one can see it, are you still in a forest? Knock on wood.' FROM games WHERE igdb_id = 132706 ON CONFLICT (game_id, language_code) DO NOTHING;
