INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HideNSeek', 'The HideNSeek Beta was a game demo by Innersloth, mainly worked on by Forest Willard, with features that were planned to be in Among Us 2. It requires ten people to start a game. Players must be in the Innersloth Discord server and link their account to play, and high scores would be recorded in a channel.[' FROM games WHERE igdb_id = 201079 ON CONFLICT (game_id, language_code) DO NOTHING;
