INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Two Parsecs From Earth', 'Two Parsecs From Earth gameplay is remarkable interactive and adaptive to you! Choose 3 abilities during the exploration and experience your adventure in 8 different ways according to your own decisions, accompanied by music that adapts to your abilities choices. Once the adventure is over, you have the opportunity to do it again differently in the unique "New game+" mode integrated into the story!' FROM games WHERE igdb_id = 140786 ON CONFLICT (game_id, language_code) DO NOTHING;
