INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Under Night In-Birth Exe:Late[cl-r]', 'The next installment in the Under Night In-Birth 2D fighting game saga is coming to North America. Developed by acclaimed 2D fighting game studio French Bread, Under Night In-Birth Exe:Late[cl-r] will feature a new playable character and updates to the game which include nearly a thousand balance changes and new moves. A demo of the game will be available at special events.' FROM games WHERE igdb_id = 121369 ON CONFLICT (game_id, language_code) DO NOTHING;
