INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tech Glitch', 'An old school couch multiplayer game. Get your friends and compete against each other. Multiple game modes? Check. Many maps? Check. Power-Ups! Check. This old school local multiplayer game will not forgive you for any mistakes. Nothing is decided until the clocks stop ticking. You can always flip the tables and win spectacularly.' FROM games WHERE igdb_id = 140949 ON CONFLICT (game_id, language_code) DO NOTHING;
