INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CBT With Yuuka Kazami', 'Cognitive Behavioral Therapy, also known as CBT, is the use of evidence based strategies to help manage symptoms of poor mental health problems such as stress, anxiety and depression. Yuuka Kazami from the Touhou Project invites you to some mostly peaceful lessons where you grasp the basics of CBT!' FROM games WHERE igdb_id = 143220 ON CONFLICT (game_id, language_code) DO NOTHING;
