INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boris and the Dark Survival', 'Play as Boris the Wolf, the cartoon companion of Bendy, as you hunt throughout the abandoned cartoon studio for the supplies Boris needs to keep going. You’re not alone! The monstrous Ink Demon stalks you at every turn. Beware the sound of his beating heart as he creeps up from behind and catches you in his dripping gaze. No where is safe. Yet secrets lie in wait for those adventurous enough to seek them out.' FROM games WHERE igdb_id = 129677 ON CONFLICT (game_id, language_code) DO NOTHING;
