INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape from Life Inc', 'Escape from Life Inc is a quirky platformer with a capturing story. (literally) You can switch between the three main characters: Bob, a walking fish, Ern, an eagle, and Rick, a stuttering reindeer. They each have unique abilities. Throughout your adventure you''ll be doing puzzles, platforming, exploring and much more. Together with plenty of wacky characters who are all talking animals, help them escape the alien lab!INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 125739 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
