INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candy 2048 Challenge', 'Candy 2048 Challenge brings back the iconic 2048 game with a new multiplayer function. It takes the intense fun of the original 2048 and pits you against one other friend, to really see who is the best! Test your intelligence in this infinite puzzle game, featuring a split-screen multiplayer mode for a 1 vs. 1 challenge, fun and addictive music, and a local leaderboard.' FROM games WHERE igdb_id = 147132 ON CONFLICT (game_id, language_code) DO NOTHING;
