INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrine II', 'The Eldritch horde returns in Shrine II! Shrine II is a total conversion mod for Doom 2. Tusk is back, and his rage won''t be quelled! Journey through five dimensions to find the source of the corruption in this 32 level total conversion for doom 2! Including: -Over 20 unique Demons to slay -Boss Battles Galore -Over 20 unique weapons -32 levels -Tons of secrets and replayability -A challenging yet fair difficulty' FROM games WHERE igdb_id = 135474 ON CONFLICT (game_id, language_code) DO NOTHING;
